class Solution {
public:
    vector<int> trainingPlan(vector<int>& nums) {
        int j = 0;
        for (int i = 0; i < nums.size(); ++i) {
            if (nums[i] & 1) {
                swap(nums[i], nums[j++]);
            }
        }
        return nums;
    }
};
